import React from "react"
import { View, Text, StyleSheet } from "react-native"
import { Screen } from "@/components/Screen"
import DraggableFlatList from "react-native-draggable-flatlist"
import { RoutineCard } from "./../../components/Routines/RoutineCard"
import { useRoutines, RoutineWithExercises } from "../../../hooks/useRoutines"
import { db } from "@/utils/storage"
import { routines, routineExercises, routineSets } from "@/utils/storage/schema"
import { sql } from "drizzle-orm"
import cuid from "cuid";
import { Ionicons } from "@expo/vector-icons"
import LoadingOverlay from "@/components/LoadingOverlay"

const getFullRoutineData = async (routineId: string) => {
  const routineExerciseRows = await db
    .select()
    .from(routineExercises)
    .where(sql`${routineExercises.routineId} = ${routineId}`)

  return Promise.all(
    routineExerciseRows.map(async (re) => {
      const sets = await db
        .select()
        .from(routineSets)
        .where(
          sql`${routineSets.routineId} = ${routineId}
              AND ${routineSets.exerciseId} = ${re.exerciseId}`
        )

      return {
        exerciseId: re.exerciseId,
        notes: re.notes,
        unit: re.unit,
        repsType: re.repsType,
        restTimer: re.restTimer,
        sets,
      }
    })
  )
}

export default function RoutineScreen() {
  const { routinesData, setRoutinesData, loading } = useRoutines()
  const handleDelete = async (id: string) => {
    try {
      await db.delete(routineSets).where(sql`${routineSets.routineId} = ${id}`)
      await db.delete(routineExercises).where(sql`${routineExercises.routineId} = ${id}`)
      await db.delete(routines).where(sql`${routines.id} = ${id}`)
      setRoutinesData(routinesData.filter((r) => r.id !== id))
    } catch (error) {
      console.error("Failed to delete routine:", error)
    }
  }

const handleDuplicate = async (routine: RoutineWithExercises) => {
  try {
    const newRoutineId = cuid()

    // 1️⃣ Duplicate routine
    await db.insert(routines).values({
      id: newRoutineId,
      name: routine.title + " (Copy)",
      createdBy: null,
      isPreMade: 0,
      level: "beginner",
      description: "",
    })

    // 2️⃣ Fetch FULL routine data (🔥 KEY FIX)
    const fullExercises = await getFullRoutineData(routine.id)

    // 3️⃣ Duplicate exercises + sets
    for (const ex of fullExercises) {
      await db.insert(routineExercises).values({
        id: cuid(),
        routineId: newRoutineId,
        exerciseId: ex.exerciseId,
        notes: ex.notes ?? "",
        unit: ex.unit ?? "kg",
        repsType: ex.repsType ?? "reps",
        restTimer: ex.restTimer ?? 0,
      })

      for (const set of ex.sets) {
        await db.insert(routineSets).values({
          id: cuid(),
          routineId: newRoutineId,
          exerciseId: ex.exerciseId,
          weight: set.weight ?? 0,
          reps: set.reps ?? 0,
          minReps: set.minReps ?? null,
          maxReps: set.maxReps ?? null,
          duration: set.duration ?? 0,
          setType: set.setType ?? "Normal",
        })
      }
    }

    // 4️⃣ Optimistic UI update
    setRoutinesData([
      {
        ...routine,
        id: newRoutineId,
        title: routine.title + " (Copy)",
      },
      ...routinesData,
    ])
  } catch (error) {
    console.error("Failed to duplicate routine:", error)
  }
}


  if (loading) {
    return (
      <Screen contentContainerStyle={styles.center}>
            <LoadingOverlay visible={loading} message="Loading routines..." />
      </Screen>
    )
  }

  if (!routinesData.length) {
  return (
    <Screen
      contentContainerStyle={[
        styles.center,
        { paddingHorizontal: 20,backgroundColor: "#000000ff", },
      ]}
    >
      {/* Icon */}
      <Ionicons
        name="barbell-outline"
        size={90}
        color="#666"
        style={{ marginBottom: 20 }}
      />

      {/* Title */}
      <Text
        style={{
          color: "#fff",
          fontSize: 24,
          fontWeight: "bold",
          marginBottom: 8,
        }}
      >
        No Routines Yet
      </Text>

      {/* Subtitle */}
      <Text
        style={{
          color: "#aaa",
          fontSize: 16,
          textAlign: "center",
          marginBottom: 25,
          width: "85%",
        }}
      >
        Create your first workout routine and start building consistency!
      </Text>

     
    </Screen>
  )
}

  return (
    <Screen contentContainerStyle={styles.container}>
      <DraggableFlatList
        data={routinesData}
        keyExtractor={(item) => item.id}
        renderItem={(params) => (
          <RoutineCard {...params} onDelete={handleDelete} onDuplicate={handleDuplicate} />
        )}
        onDragEnd={({ data }) => setRoutinesData(data)}
        activationDistance={10}
        animationConfig={{ damping: 20, mass: 0.8, stiffness: 120 }}
        contentContainerStyle={styles.listContainer}
      />
    </Screen>
  )
}

const styles = StyleSheet.create({
  container: { flexGrow: 1, paddingVertical: 10, backgroundColor: "#000000ff", },
  listContainer: { paddingHorizontal: 20, paddingBottom: 20 },
  center: { flex: 1, justifyContent: "center", alignItems: "center" },
})
